use super::*;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};

#[test]
fn sqlite_snapshot_original_physical_final_prefix_has_no_unfunded_release(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 let database=SqliteDatabase{tables:vec![SqliteTable{name:law["table"].as_str().unwrap().into(),sql:law["sql"].as_str().unwrap().into(),rows:vec![SqliteRow{rowid:1,values:vec![SqliteValue::Integer(1),SqliteValue::Text(law["text"].as_str().unwrap().into())]}]}]};
 let limits=SqliteDatabaseLimits{max_file_bytes:law["sqlLimits"]["maxFileBytes"].as_u64().unwrap()as usize,max_value_bytes:law["sqlLimits"]["maxValueBytes"].as_u64().unwrap()as usize,max_allocation_bytes:law["sqlLimits"]["maxAllocationBytes"].as_u64().unwrap()as usize,max_schema_bytes:law["sqlLimits"]["maxSchemaBytes"].as_u64().unwrap()as usize,max_rows:law["sqlLimits"]["maxRows"].as_u64().unwrap()as usize,max_columns:law["sqlLimits"]["maxColumns"].as_u64().unwrap()as usize,max_tables:law["sqlLimits"]["maxTables"].as_u64().unwrap()as usize,max_pages:law["sqlLimits"]["maxPages"].as_u64().unwrap()as usize};
 let expected=law["expectedFileBytes"].as_u64().unwrap()as usize;
 let baseline=export_sqlite_database(&database,limits,&mut |_|true).unwrap();assert_eq!(baseline.len(),expected);
 let script="const {Database}=require('bun:sqlite');(async()=>{const chunks=[];for await(const c of process.stdin)chunks.push(c);const db=Database.deserialize(Buffer.concat(chunks));try{console.log(JSON.stringify(db.query('SELECT CAST(id AS TEXT) AS id,text FROM document').get()))}finally{db.close()}})()";
 use std::{io::Write,process::{Command,Stdio}};
 let mut oracle=Command::new("bun").args(["--eval",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&baseline).unwrap();let observation=oracle.wait_with_output().unwrap();assert!(observation.status.success(),"{}",String::from_utf8_lossy(&observation.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&observation.stdout).unwrap(),serde_json::json!({"id":law["rowid"],"text":law["text"]}));
 let final_birth=AtomicBool::new(false);let owned=AtomicUsize::new(0);let events=AtomicUsize::new(0);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;
 let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{owned.store(request.next_owned_bytes,Ordering::Relaxed);if request.bytes==expected{final_birth.store(true,Ordering::Relaxed)}Ok(())};
 let mut observe=|_:semio_framework_value::native_decoding::NativeDecodeProgress|{if !final_birth.load(Ordering::Relaxed){return true}events.fetch_add(1,Ordering::Relaxed);events.load(Ordering::Relaxed)<law["cancelFinalCheckpoint"].as_u64().unwrap()as usize};
 let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut native=semio_framework_value::NativeDecodeControl::new_forwarded(maximum,&mut observe,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();
 let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(law["originalGrant"].clone()).unwrap();
 let prefix=AtomicUsize::new(0);let mut owner=crate::original_control::NativeSnapshotDecodeOwner::new(&mut native,grant);
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalExportFrame,()>(|slot,native,body|{*slot=Some(PhysicalExportFrame::new());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Decode(native),body};let result=export_sqlite_database_receiving_into(&database,slot.as_mut().unwrap(),&mut port);prefix.store(slot.as_ref().unwrap().output.len(),Ordering::Relaxed);result}));
 let error=result.unwrap_err();assert_eq!(prefix.load(Ordering::Relaxed),law["expectedRefusedPrefixBytes"].as_u64().unwrap()as usize);assert_eq!(error.kind.as_str(),law["expectedRefusalKind"].as_str().unwrap());assert_eq!(error.message,law["expectedDirectNativeRefusalMessage"].as_str().unwrap());assert!(final_birth.load(Ordering::Relaxed));assert!(events.load(Ordering::Relaxed)>=law["cancelFinalCheckpoint"].as_u64().unwrap()as usize);assert!(born>=expected+law["pageBytes"].as_u64().unwrap()as usize);let performed=owner.progress();drop(owner);
 eprintln!("[DEBUG] Actual original SQLite receiving final-prefix cancellation born={born} released={released} nativeOwned={} actualPort={} originalObserverEvents={} actualBody={performed:?}",native.owned_bytes(),owned.load(Ordering::Relaxed),events.load(Ordering::Relaxed));
 assert_eq!(released,law["expectedRefusedReleasedBytes"].as_u64().unwrap()as usize,"refused final output and every writer scratch owner must remain in original funded custody");assert!(native.has_retirement_owner());
 final_birth.store(false,Ordering::Relaxed);let(zero,zero_born,zero_released)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(Default::default()).unwrap());assert_eq!((zero.progress(),zero_born,zero_released),(Default::default(),0,0));let mut cleanup_born=0;let mut cleanup_released=0;for _ in 0..law["maximumRetirementTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(grant).unwrap());assert_eq!((b,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));cleanup_born+=b;cleanup_released+=r;}assert!(!native.has_retirement_owner());assert_eq!(cleanup_released,born+cleanup_born);eprintln!("[DEBUG] Actual original SQLite frame funded cleanup totalBorn={} totalReleased={cleanup_released}",born+cleanup_born);
}

fn original_fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn original_limits(f:&serde_json::Value)->SqliteDatabaseLimits{let p=&f["sqlLimits"];SqliteDatabaseLimits{max_file_bytes:p["maxFileBytes"].as_u64().unwrap()as usize,max_value_bytes:p["maxValueBytes"].as_u64().unwrap()as usize,max_allocation_bytes:p["maxAllocationBytes"].as_u64().unwrap()as usize,max_schema_bytes:p["maxSchemaBytes"].as_u64().unwrap()as usize,max_rows:p["maxRows"].as_u64().unwrap()as usize,max_columns:p["maxColumns"].as_u64().unwrap()as usize,max_tables:p["maxTables"].as_u64().unwrap()as usize,max_pages:p["maxPages"].as_u64().unwrap()as usize}}
fn original_database(f:&serde_json::Value)->SqliteDatabase{SqliteDatabase{tables:vec![SqliteTable{name:f["table"].as_str().unwrap().into(),sql:f["sql"].as_str().unwrap().into(),rows:vec![SqliteRow{rowid:1,values:vec![SqliteValue::Integer(1),SqliteValue::Text(f["text"].as_str().unwrap().into())]}]}]}}
#[test]
fn sqlite_snapshot_original_physical_empty_frames_allocate_nothing(){let((export,import),born,released)=semio_framework_trace_memory_testing::observe_backing(||(PhysicalExportFrame::new(),PhysicalImportFrame::new()));assert_eq!((born,released),(0,0));assert!(export.output.is_empty());assert!(import.database.tables.is_empty());assert_eq!(semio_framework_trace_memory_testing::observe_backing(||drop((export,import))),((),0,0));eprintln!("[DEBUG] Original physical frame constructors exact heap born=0 released=0");}
#[test]
fn sqlite_snapshot_original_physical_success_uses_both_real_owners_and_exact_funded_scratch(){
 let f=original_fixture();let limits=original_limits(&f);let database=original_database(&f);let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(f["originalGrant"].clone()).unwrap();let maximum=f["nativeMaximumBytes"].as_u64().unwrap()as usize;
 let mut decode_progress=|_|true;let mut decode_recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut decode=semio_framework_value::NativeDecodeControl::new(maximum,&mut decode_progress);decode.install_retirement_recipient(&mut decode_recipient).unwrap();let mut decoder=crate::original_control::NativeSnapshotDecodeOwner::new(&mut decode,grant);
 let(exported,born,released)=semio_framework_trace_memory_testing::observe_backing(||decoder.receive::<PhysicalExportFrame,Vec<u8>>(|slot,native,body|{*slot=Some(PhysicalExportFrame::new());let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,limits);let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Decode(native),body};export_sqlite_database_receiving_into(&database,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<Vec<u8>>())?;Ok(std::mem::take(&mut slot.as_mut().unwrap().output))}));let file=exported.unwrap();assert_eq!(file.len(),f["expectedFileBytes"].as_u64().unwrap()as usize);assert_eq!(born,released+file.capacity());assert_eq!(decoder.progress().retained_capacity_bytes,born);assert_eq!(decoder.progress().released_bytes,released);drop(decoder);assert!(!decode.has_retirement_owner());assert_eq!(import_sqlite_database(&file,limits,&mut |_|true).unwrap(),database);
 use std::{io::Write,process::{Command,Stdio}};let script="const {Database}=require('bun:sqlite');(async()=>{const chunks=[];for await(const c of process.stdin)chunks.push(c);const db=Database.deserialize(Buffer.concat(chunks));try{console.log(JSON.stringify({row:db.query('SELECT CAST(id AS TEXT) AS id,text FROM document').get(),integrity:db.query('PRAGMA integrity_check').get()}))}finally{db.close()}})()";let mut oracle=Command::new("bun").args(["--eval",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&file).unwrap();let observation=oracle.wait_with_output().unwrap();assert!(observation.status.success(),"{}",String::from_utf8_lossy(&observation.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&observation.stdout).unwrap(),serde_json::json!({"row":{"id":f["rowid"],"text":f["text"]},"integrity":{"integrity_check":"ok"}}));
 let mut encode_progress=|_|true;let mut encode_recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut encode=semio_framework_value::NativeEncodeControl::new(maximum,&mut encode_progress);encode.install_retirement_recipient(&mut encode_recipient).unwrap();let mut encoder=crate::original_control::NativeSnapshotEncodeOwner::new(&mut encode,grant);
 let(imported,import_born,import_released)=semio_framework_trace_memory_testing::observe_backing(||encoder.receive::<PhysicalImportFrame,SqliteDatabase>(|slot,native,body|{*slot=Some(PhysicalImportFrame::new());let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,limits);let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Encode(native),body};import_sqlite_database_receiving_into(&file,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<SqliteDatabase>())?;Ok(std::mem::replace(&mut slot.as_mut().unwrap().database,SqliteDatabase{tables:Vec::new()}))}));let actual=imported.unwrap();assert_eq!(actual,database);assert_eq!(encoder.progress().retained_capacity_bytes,import_born);assert_eq!(encoder.progress().released_bytes,import_released);drop(encoder);assert!(!encode.has_retirement_owner());let(_,_,output_backing)=semio_framework_trace_memory_testing::observe_backing(||drop(actual));assert_eq!(import_born,import_released+output_backing);eprintln!("[DEBUG] Original physical writer/parser whole-cell equality: exportBorn={born} exportReleased={released} output={} importBorn={import_born} importReleased={import_released} relationalOutput={output_backing}",file.capacity());
}
#[test]
fn sqlite_snapshot_original_physical_parser_canceled_text_prefix_remains_with_original_encoder(){
 let f=original_fixture();let database=original_database(&f);let limits=original_limits(&f);let file=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let text=f["text"].as_str().unwrap();let maximum=f["nativeMaximumBytes"].as_u64().unwrap()as usize;let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(f["originalGrant"].clone()).unwrap();let live=AtomicBool::new(true);let copied=AtomicBool::new(false);let mut progress=|event:semio_framework_value::native_encoding::NativeEncodeProgress|{if event.total==text.len()&&event.completed==text.len(){copied.store(true,Ordering::Relaxed);live.store(false,Ordering::Relaxed)}live.load(Ordering::Relaxed)};let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut native=semio_framework_value::NativeEncodeControl::new(maximum,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=crate::original_control::NativeSnapshotEncodeOwner::new(&mut native,grant);
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalImportFrame,()>(|slot,native,body|{*slot=Some(PhysicalImportFrame::new());let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,limits);let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Encode(native),body};import_sqlite_database_receiving_into(&file,slot.as_mut().unwrap(),&mut port)}));let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.message,f["expectedEncoderRefusalMessage"].as_str().unwrap());assert!(copied.load(Ordering::Relaxed));assert_eq!(released,0);let performed=owner.progress();assert_eq!(performed.retained_capacity_bytes,born);drop(owner);assert!(native.has_retirement_owner());live.store(true,Ordering::Relaxed);
 let mut extra=0;let mut retired=0;for _ in 0..f["maximumRetirementTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(grant).unwrap());assert_eq!((b,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));extra+=b;retired+=r;}assert!(!native.has_retirement_owner());assert_eq!(retired,born+extra);eprintln!("[DEBUG] Original encoder/parser canceled text prefix: born={born} refusedReleased={released} fullCause={} fundedBorn={} fundedReleased={retired} actualBody={performed:?}",error.message,born+extra);
}

#[test]
fn sqlite_snapshot_original_physical_overflow_tree_preserves_all_cells_against_independent_sqlite(){
 let f=original_fixture();let forest=&f["forest"];let limits=original_limits(&f);let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(f["originalGrant"].clone()).unwrap();let maximum=f["nativeMaximumBytes"].as_u64().unwrap()as usize;let first=forest["firstRowId"].as_i64().unwrap();let seed=forest["textSeed"].as_str().unwrap();let blob=forest["blob"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>();let mut expected=Vec::new();let mut rows=Vec::new();
 for i in 0..forest["rows"].as_u64().unwrap(){let rowid=first+i as i64;let repeats=if i==0{forest["firstTextRepeats"].as_u64().unwrap()}else{forest["otherTextRepeats"].as_u64().unwrap()}as usize;let text=seed.repeat(repeats);expected.push(serde_json::json!({"id":rowid.to_string(),"blobHex":"0001FF80","kind":"real","value":forest["real"],"textBytes":text.len()}));rows.push(SqliteRow{rowid,values:vec![SqliteValue::Integer(rowid),SqliteValue::Text(text),SqliteValue::Blob(blob.clone()),SqliteValue::Real(forest["real"].as_f64().unwrap())]});}assert_eq!(rows.last().unwrap().rowid,forest["lastRowId"].as_i64().unwrap());let database=SqliteDatabase{tables:vec![SqliteTable{name:forest["table"].as_str().unwrap().into(),sql:forest["sql"].as_str().unwrap().into(),rows}]};
 let mut progress=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut native=semio_framework_value::NativeDecodeControl::new(maximum,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=crate::original_control::NativeSnapshotDecodeOwner::new(&mut native,grant);
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalExportFrame,Vec<u8>>(|slot,native,body|{*slot=Some(PhysicalExportFrame::new());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Decode(native),body};export_sqlite_database_receiving_into(&database,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<Vec<u8>>())?;Ok(std::mem::take(&mut slot.as_mut().unwrap().output))}));let file=result.unwrap();assert!(file.len()>3*f["pageBytes"].as_u64().unwrap()as usize);assert_eq!(file.len()%f["pageBytes"].as_u64().unwrap()as usize,0);assert_eq!(born,released+file.capacity());assert_eq!((owner.progress().retained_capacity_bytes,owner.progress().released_bytes),(born,released));drop(owner);assert!(!native.has_retirement_owner());
 use std::{io::Write,process::{Command,Stdio}};let script="const {Database}=require('bun:sqlite');(async()=>{const chunks=[];for await(const c of process.stdin)chunks.push(c);const db=Database.deserialize(Buffer.concat(chunks));try{console.log(JSON.stringify({rows:db.query('SELECT CAST(id AS TEXT) AS id,hex(blob) AS blobHex,typeof(value) AS kind,value,length(CAST(text AS BLOB)) AS textBytes FROM payload ORDER BY payload.id').all(),integrity:db.query('PRAGMA integrity_check').get()}))}finally{db.close()}})()";let mut oracle=Command::new("bun").args(["--eval",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&file).unwrap();let observation=oracle.wait_with_output().unwrap();assert!(observation.status.success(),"{}",String::from_utf8_lossy(&observation.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&observation.stdout).unwrap(),serde_json::json!({"rows":expected,"integrity":{"integrity_check":"ok"}}));
 let mut progress=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut native=semio_framework_value::NativeEncodeControl::new(maximum,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=crate::original_control::NativeSnapshotEncodeOwner::new(&mut native,grant);let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalImportFrame,SqliteDatabase>(|slot,native,body|{*slot=Some(PhysicalImportFrame::new());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Encode(native),body};import_sqlite_database_receiving_into(&file,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<SqliteDatabase>())?;Ok(std::mem::replace(&mut slot.as_mut().unwrap().database,SqliteDatabase{tables:Vec::new()}))}));let actual=result.unwrap();assert_eq!(actual,database);assert_eq!((owner.progress().retained_capacity_bytes,owner.progress().released_bytes),(born,released));drop(owner);assert!(!native.has_retirement_owner());let(_,_,output_backing)=semio_framework_trace_memory_testing::observe_backing(||drop(actual));assert_eq!(born,released+output_backing);eprintln!("[DEBUG] Actual original physical signed300row interior/overflow tree, Blob/Real/NUL/CRLF exact independent SQLite: fileBytes={} parserBorn={born} parserReleased={released} publishedBacking={output_backing}",file.len());
}
